        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::theme::init(cx);
            gpui_kit::component::Theme::change(gpui_kit::component::ThemeMode::Dark, None, cx);
        });
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|_| Locked(ScrollHandle::new()));
            Root::new(view, window, cx)
        });
        let handle = window.into();
