        Button::new(SharedString::from(format!("{id}-{name}")))
            .ghost()
            .xsmall()
            .icon(icon)
            .w(COLUMN_WIDTH)
            .h(COLUMN_WIDTH)
            .rounded_none()
            .border_l_1()
            .border_color(border)
    };
    let follow = follower(handle, &lock);
            // Whether the pointer was over the thumb when last drawn.
